from pathlib import Path
import sys,json
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from grenade.runner import load_queries,ROOT
import pandas as pd
import plotly.express as px
rows=load_queries(ROOT/'config/queries.csv')
counts=pd.DataFrame(rows).groupby('category').size().reset_index(name='Queries')
fig=px.bar(counts,x='category',y='Queries',color='category',template='plotly_dark')
fig.update_layout(paper_bgcolor='#18211f',plot_bgcolor='#18211f',showlegend=False,margin=dict(t=20,b=20),font_color='#f0f5ed')
chart=fig.to_html(full_html=False,include_plotlyjs=True)
frame=pd.DataFrame(rows)[['query','category','priority','language','branded']].to_html(index=False,escape=True)
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Grenade / Search intelligence preview</title><style>
*{box-sizing:border-box}body{margin:0;background:#101715;color:#edf4e9;font:16px system-ui;display:flex}aside{width:245px;padding:32px 22px;background:#18211f;min-height:100vh;position:fixed}main{margin-left:245px;padding:45px;max-width:1450px;width:calc(100% - 245px)}h1{font-size:42px;letter-spacing:-2px;margin:12px 0}h2{font-size:25px;letter-spacing:-.5px}.tag{color:#b6ef48;font-weight:700;font-size:12px;letter-spacing:2px}.muted{color:#aebeb1}.notice{border:1px solid #5b6446;background:#252c1f;padding:18px;border-radius:10px;margin:24px 0}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.card{padding:22px;background:#1b2722;border-radius:12px;border-top:3px solid #b6ef48}.value{font-size:32px;font-weight:700;margin-top:14px}.button{border:0;background:transparent;color:#cfdbce;display:block;padding:15px 10px;width:100%;text-align:left;border-radius:8px;cursor:pointer}.button:hover,.button.active{background:#32402c;color:#b6ef48}.panel{display:none}.panel.active{display:block}table{border-collapse:collapse;width:100%;font-size:13px}td,th{padding:10px;text-align:left;border-bottom:1px solid #344236}th{color:#b6ef48;position:sticky;top:0;background:#18211f}.scroll{overflow:auto;max-height:650px}li{margin:13px 0}code{color:#b6ef48}@media(max-width:800px){aside{position:static;width:100%;min-height:0}body{display:block}main{margin:0;width:100%;padding:22px}.cards{grid-template-columns:1fr}h1{font-size:32px}}
</style><aside><div class="tag">GRENADE / CANADA</div><h2>Search intelligence</h2><p class="muted">Local research workbench</p>'''
pages=['Executive Overview','Keyword Explorer','Competitor Intelligence','Technical & GEO Audit','Action Plan']
for i,name in enumerate(pages):html+=f'<button class="button {"active" if i==0 else ""}" onclick="show({i},this)">{name}</button>'
html+='''<p class="muted" style="margin-top:50px">EXAMPLE DASHBOARD<br>Unmeasured initial state<br>No sample SERPs</p></aside><main><div class="tag">VISIBILITY INTELLIGENCE · RESEARCH READY</div><h1>Find the visibility.<br>Follow the evidence.</h1><p class="muted">Canadian acquisition queries. Reproducible evidence. Transparent priorities.</p><div class="notice">No live search data is available. Save your key in .env and use the built-in Search/Fetch test before collection. This preview shows configured research coverage, not brand performance.</div>'''
html+='<section id="p0" class="panel active"><div class="cards"><div class="card">Queries configured<div class="value">115</div></div><div class="card">Queries without Grenade<div class="value">102</div></div><div class="card">Grenade visibility<div class="value">Not measured</div></div></div><h2>Research coverage by intent</h2>'+chart+'<p class="muted">These counts describe the query library only. No competitor visibility or commercial impact has been measured.</p></section>'
html+='<section id="p1" class="panel"><h2>Keyword Explorer</h2><p class="muted">115 configured queries · priority is a planning judgment, not volume.</p><div class="scroll">'+frame+'</div></section>'
html+='<section id="p2" class="panel"><h2>Competitor Intelligence</h2><p>Tracking configured for Grenade, Barebells, Quest, ONE, Pure Protein, Built, RXBAR and Kirkland Signature.</p><p class="muted">No competitive rankings, result ownership, publisher dominance or content themes are observed yet. Additional brand candidates require review.</p></section>'
html+='<section id="p3" class="panel"><h2>Technical &amp; GEO Audit</h2><p>Ownership validation required before official site findings can be collected.</p><p class="muted">No technical defects have been established. GEO readiness will be a page-level diagnostic heuristic, not a probability of AI recommendations. Product fact consistency and actual AI platform visibility remain unmeasured.</p></section>'
html+='<section id="p4" class="panel"><h2>Action Plan</h2><p>Operational prerequisites, ordered by dependency:</p><ol><li>Use the built-in Search/Fetch connection test to confirm account access.</li><li>Validate official domains and Canadian retailer availability.</li><li>Run the 10-query test, inspect raw responses, then expand the baseline.</li><li>Validate candidate content, retailer and publisher gaps with fetched evidence.</li><li>Import demand, stock and sales data before estimating commercial impact.</li></ol><p class="muted">Evidence-ranked SEO opportunities will appear after a successful audit. No traffic or revenue lift is forecast.</p><code>streamlit run app.py</code></section>'
html+='''</main><script>function show(i,button){document.querySelectorAll('.panel').forEach(x=>x.classList.remove('active'));document.getElementById('p'+i).classList.add('active');document.querySelectorAll('.button').forEach(x=>x.classList.remove('active'));button.classList.add('active');window.dispatchEvent(new Event('resize'));}</script></html>'''
(ROOT/'reports/dashboard-preview.html').write_text(html)
